      '    provider: spawn',
      `    toolName: ${member.toolName}`,
      '    backgroundMode: continuable',
      '    persona: |-',
      ...member.persona.replaceAll('\r\n', '\n').split('\n').map(line => `      ${line}`),
      '',
    )
  }
  if (block.length > 0) lines.splice(insertAt, 0, ...block, '# ── expert team member delegation rows (generated) ──', '')
