const SCRIPT_EXTENSIONS = ['.py', '.sh', '.ps1', '.bat', '.cmd']
const ALLOWED_EXTENSIONS = ['.md', '.json', '.yaml', '.yml', '.txt', '.png', '.jpg', '.jpeg', '.webp', '.gif']

